            s = st(S)
            Rs = GA.mul(R, s, sq)
            ok = ok and not GA.is_zero(s) and not GA.is_zero(Rs)
            ok = ok and index_set(s) == frozenset(S)
            ok = ok and index_set(Rs) == frozenset(range(3)) - frozenset(S)
