    ok = ok and count == 8
    GA.check("prop:arrow(i): the flag conjugate e3 e4 e5 maps creation set S to its complement (grades k <-> 3 - k) "
             "on all 8 Fock states, R^2 = 1, w_i -> v_i", ok)
    return ok


def check_theta_exists_exactly_where_the_bit_does():
