dark-matter.democracy-de-sitter-radius-u:
"""dark-matter.democracy-de-sitter-radius-unit-ball: exact checks.

Numbers of Q(pi) are Laurent polynomials in pi, {k: c} for sum c pi^k (pi transcendental); the
unit-ball volumes come from V_0 = 1, V_1 = 2, V_D = (2 pi / D) V_(D-2) and the unit-sphere areas
from |S^(n-1)| = n V_n.

Checked:
(1) Under D a tower of spacetime dimension n has density M/(|S^n| l^n) on its sphere; read through
    a thickness l (n = 5) or with sheets l apart (n = 3) it is a density per unit of our
    four-measure, and the share against ours, M/(|S^4| l^4), is |S^4|/|S^n|: M and l cancel
    (checked at two sample values of each) for n = 3, 4, 5.
(2) The sphere form equals the ball form: |S^n| = 2 pi V_(n-1) (hat-box identity, n = 1..7), so
    |S^4|/|S^n| = V_3/V_(n-1): 4/3 at n = 3 and 8/(3 pi) at n = 5.
(3) The total over the dark towers (n = 4 once, n = 3 and n = 5 twice each) is the unit-ball
    rule's 11/3 + 16/(3 pi).
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

MASSES = [F(1), F(17, 3)]          # sample total masses M_tot (D: common to all towers)
LENGTHS = [F(1), F(5, 2)]          # sample de Sitter radii l
DARK_N = [4, 3, 3, 5, 5]           # mirror, two three-dimensional, two five-dimensional towers


def lp(c, k=0):
    return {k: F(c)} if c != 0 else {}


def ladd(*xs):
    out = {}
    for x in xs:
        for k, c in x.items():
            out[k] = out.get(k, F(0)) + c
    return {k: c for k, c in out.items() if c != 0}


def lmul(*xs):
    out = {0: F(1)}
    for b in xs:
        new = {}
        for k1, c1 in out.items():
            for k2, c2 in b.items():
                new[k1 + k2] = new.get(k1 + k2, F(0)) + c1 * c2
        out = {k: c for k, c in new.items() if c != 0}
    return out


def linv(a):
    assert len(a) == 1
    (k, c), = a.items()
    return {-k: 1 / c}


def ball(D):
    V = {0: lp(1), 1: lp(2)}
    for n in range(2, D + 1):
        V[n] = lmul(lp(F(2, n), 1), V[n - 2])
    return V[D]


def sphere(k):
    """|S^k|, the area of the unit sphere in R^(k+1)"""
    return lmul(lp(k + 1), ball(k + 1))


def share(n, M, l):
    dens = lmul(lp(M / l ** n), linv(sphere(n)))           # D: density on the tower's sphere
    per_ours = lmul(dens, lp(l ** (n - 4)))                  # R3 at the unit l
    ours = lmul(lp(M / l ** 4), linv(sphere(4)))
    return lmul(per_ours, linv(ours))


def check_shares_are_sphere_ratios():
    premise("dark-matter.d-democracy-total-mass")
    premise("dark-matter.r3-one-cell-per-unshared-direction")
    for M in MASSES:
        for l in LENGTHS:
            for n in (3, 4, 5):
                assert share(n, M, l) == lmul(sphere(4), linv(sphere(n)))
    assert sphere(4) == {2: F(8, 3)} and sphere(3) == {2: F(2)} and sphere(5) == {3: F(1)}
    return True


def check_sphere_form_is_ball_form():
    for n in range(1, 8):
        assert sphere(n) == lmul(lp(2, 1), ball(n - 1))
    assert lmul(sphere(4), linv(sphere(3))) == {0: F(4, 3)}
    assert lmul(sphere(4), linv(sphere(5))) == {-1: F(8, 3)}
    assert lmul(sphere(4), linv(sphere(3))) == lmul(ball(3), linv(ball(2)))
    assert lmul(sphere(4), linv(sphere(5))) == lmul(ball(3), linv(ball(4)))
    return True


def check_total_is_unit_ball_rule():
    premise("dark-matter.d-democracy-total-mass")
    premise("dark-matter.r3-one-cell-per-unshared-direction")
    total = ladd(*[share(n, MASSES[1], LENGTHS[1]) for n in DARK_N])
    assert total == {0: F(11, 3), -1: F(16, 3)}
    return True

dark-matter.imported-eight-towers-mod-8-:
"""dark-matter.imported-eight-towers-mod-8-clock: exact checks.

Floors T_k = Cl(p+k, q+k) in GA.py (ground generators first, then the planes e_j, f_j with squares
+1, -1). Checked:
(1) the (1,1) ascent preserves p - q, and Cl(p+k, q+k) = Mat_{2^k}(Cl(p,q)): the twisted ground
    generators x Omega_k satisfy the ground relations and commute with every plane generator; the
    plane algebra B_k has 4^k matrix units E_{ST} = v_S f v_T^dagger (f the vacuum projector) with
    E_{ST} E_{UW} = delta_{TU} E_{SW} and sum E_{SS} = 1, so B_k = Mat_{2^k}(R); and the products
    of A_k-words with B_k-words are 2^(n+2k) distinct basis blades (the multiplication map is an
    isomorphism). All 10 signatures with p + q <= 3 at k = 1, and the 6 with p + q <= 2 at k = 2.
(2) the period eight (Bott): Cl(p+8, q) and Cl(p, q+8) are Cl(p,q) tensor Cl(8,0) or Cl(0,8) by
    the same twist (Omega_8^2 = 1, central against the ground), and Cl(8,0), Cl(0,8) = Mat_16(R)
    exactly (an idempotent of four commuting factors whose corner f A f is R f and whose left
    ideal A f has dimension 16), for (p,q) = (1,0), (0,1).
(3) under the ascent and the shifts by eight, the signatures with p + q <= 14 fall into exactly
    eight classes, one per residue p - q mod 8.
The general k and all signatures are the cited theorem; the instances above are its finite core.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen

ASCENT_K1 = [(p, q) for p in range(4) for q in range(4) if p + q <= 3]
ASCENT_K2 = [(p, q) for p in range(3) for q in range(3) if p + q <= 2]
SHIFT_BASES = [(1, 0), (0, 1)]
FOUR_BLADES = [(0, 1, 2, 3), (4, 5, 6, 7), (0, 1, 4, 5), (0, 2, 4, 6)]


def ascent_ok(p, q, k):
    n = p + q
    sq = floor_sq(p, q, k)
    tw = twisted_ground(n, k, sq)
    ok = anticommuting_with_squares(tw, sq) == [1] * p + [-1] * q
    ok = ok and all(GA.commutes(x, GA.gen(n + i), sq) for x in tw for i in range(2 * k))
    subsets, E = matrix_units(n, k, sq)
    ok = ok and len(E) == 4 ** k and matrix_units_ok(subsets, E, sq)
    plane_gens = [GA.gen(n + i) for i in range(2 * k)]
    hit = tensor_blades(tw, plane_gens, sq)
    ok = ok and hit is not None and len(hit) == 2 ** (n + 2 * k)
    ok = ok and ((p + k) - (q + k)) % 8 == (p - q) % 8
    return ok


def check_ascent_is_matrix_amplification_one_step():
    premise("tower.commuting-copies")
    ok = all(ascent_ok(p, q, 1) for p, q in ASCENT_K1) and len(ASCENT_K1) == 10
    GA.check("Cl(p+1,q+1) = Mat_2(Cl(p,q)) with p - q fixed, all p + q <= 3", ok)
    return ok


def check_ascent_is_matrix_amplification_two_steps():
    premise("tower.commuting-copies")
    ok = all(ascent_ok(p, q, 2) for p, q in ASCENT_K2) and len(ASCENT_K2) == 6
    GA.check("Cl(p+2,q+2) = Mat_4(Cl(p,q)), all p + q <= 2", ok)
    return ok


def mat16_ok(sq8):
    """Cl(8,0) or Cl(0,8) (sq8 the squares of its 8 generators, placed first) is Mat_16(R)."""
    e = [GA.gen(i) for i in range(8)]
    us = [prod([e[i] for i in b], sq8) for b in FOUR_BLADES]
    ok = all(GA.eq(GA.mul(u, u, sq8), GA.sc(1)) for u in us)
    ok = ok and all(GA.commutes(u, w, sq8) for u in us for w in us)
    f = idempotent_from(us, sq8)
    ok = ok and GA.eq(GA.mul(f, f, sq8), f) and f.get((), F(0)) == F(1, 16)
    # corner f A f = R f: a blade anticommuting with some u_i has f b f = 0, since
    # (1 + u) b (1 + u) = b (1 - u)(1 + u) = 0; a blade commuting with all u_i has f b f = b f,
    # which must be a multiple of f
    for b in GA.all_blades(8):
        x = blade_el(b)
        if all(GA.commutes(x, u, sq8) for u in us):
            y = GA.mul(x, f, sq8)
            lam = y.get((), F(0)) / f[()]
            ok = ok and GA.eq(y, GA.scal(lam, f)) and lam in (1, -1)
        else:
            ok = ok and any(GA.anticommutes(x, u, sq8) for u in us)
    ok = ok and span_rank([GA.mul(blade_el(b), f, sq8) for b in GA.all_blades(8)], 8) == 16
    return ok


def check_period_eight():
    premise("tower.rigidity-clock-frozen")
    ok = mat16_ok((1,) * 8) and mat16_ok((-1,) * 8)
    for p, q in SHIFT_BASES:
        n = p + q
        for s8 in (1, -1):
            sq = tuple([s8] * 8 + [1] * p + [-1] * q)
            Om = prod([GA.gen(i) for i in range(8)], sq)
            ok = ok and GA.eq(GA.mul(Om, Om, sq), GA.sc(1))
            tw = [GA.mul(GA.gen(8 + i), Om, sq) for i in range(n)]
            ok = ok and anticommuting_with_squares(tw, sq) == [1] * p + [-1] * q
            ok = ok and all(GA.commutes(x, GA.gen(i), sq) for x in tw for i in range(8))
            hit = tensor_blades(tw, [GA.gen(i) for i in range(8)], sq)
            ok = ok and hit is not None and len(hit) == 2 ** (n + 8)
    GA.check("Cl(8,0) = Cl(0,8) = Mat_16(R) and Cl(p+8,q), Cl(p,q+8) = Mat_16(Cl(p,q))", ok)
    return ok


def check_eight_towers():
    premise("tower.rigidity-clock-frozen")
    premise("tower.commuting-copies")
    sigs = [(p, q) for p in range(15) for q in range(15) if p + q <= 14]
    parent = {s: s for s in sigs}

    def find(s):
        while parent[s] != s:
            s = parent[s]
        return s

    def join(a, b):
        if a in parent and b in parent:
            parent[find(a)] = find(b)

    for p, q in sigs:
        join((p, q), (p + 1, q + 1))
        join((p, q), (p + 8, q))
        join((p, q), (p, q + 8))
    classes = {}
    for s in sigs:
        get_or_set(classes, find(s), set()).add((s[0] - s[1]) % 8)
    ok = len(classes) == 8 and all(len(r) == 1 for r in classes.values())
    ok = ok and sorted(next(iter(r)) for r in classes.values()) == list(range(8))
    GA.check("ascent and period eight sort the signatures into eight towers, one per residue", ok)
    return ok

dark-matter.two-roots-are-chord-arc-quar:
"""dark-matter.two-roots-are-chord-arc-quarter: exact checks.

Numbers of Q(pi) are Laurent polynomials in pi, {k: c} for sum c pi^k (pi transcendental);
thicknesses are monomials, so c = pi/2 and c = pi are exact; decimals use rational bounds on pi.
T(c) = 1 + 8/(3c) + 16c/(3 pi) is the total of the premise.

(1) Chord and arc: on the sphere of radius R with our spacetime as its equator, the region between
    the equator and a pole has extent R along the polar axis (the pole (0, .., R) is at distance R
    from the equatorial hyperplane) and a quarter of a great circle along the surface, |S^1| R / 4
    with |S^1| = 2 V_2 = 2 pi: arc/chord = pi/2. With R = d_b the chord assignment is c = 1 and the
    arc assignment c = pi/2.
(2) The two totals agree, T(1) = T(pi/2) (identity in pi, the exchange symmetry of the premise),
    while the compositions differ: (f_3D, f_5D) = (4/3, 8/(3 pi)) at c = 1 and (8/(3 pi), 4/3) at
    c = pi/2.
(3) R2's cells: that a unit ball's extent along the added direction from its centre is its radius is the
    definition of the ball, so the selection of the chord (c = 1, against the arc's pi/2 of (1)) is
    definitional and has no separate check.
(4) Both poles: c = 2 and c = pi give T(2) = 7/3 + 32/(3 pi), which rounds to 5.729, and
    T(pi) = 19/3 + 8/(3 pi), which rounds to 7.182, each more than four sigma above 0.1200/0.02237
    (sigma 0.065): excluded.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

PI_LO, PI_HI = F(314159265358, 10 ** 11), F(314159265359, 10 ** 11)
OBS = F(1200, 10000) / F(2237, 100000)
SIG = F(65, 1000)
RADII = [F(1), F(49, 50), F(7, 3)]


def lp(c, k=0):
    return {k: F(c)} if c != 0 else {}


def ladd(*xs):
    out = {}
    for x in xs:
        for k, c in x.items():
            out[k] = out.get(k, F(0)) + c
    return {k: c for k, c in out.items() if c != 0}


def lmul(*xs):
    out = {0: F(1)}
    for b in xs:
        new = {}
        for k1, c1 in out.items():
            for k2, c2 in b.items():
                new[k1 + k2] = new.get(k1 + k2, F(0)) + c1 * c2
        out = {k: c for k, c in new.items() if c != 0}
    return out


def linv(a):
    assert len(a) == 1
    (k, c), = a.items()
    return {-k: 1 / c}


def bounds(x):
    lo = hi = F(0)
    for k, c in x.items():
        u, v = c * PI_LO ** k, c * PI_HI ** k
        lo += min(u, v)
        hi += max(u, v)
    return lo, hi


def ball(D):
    V = {0: lp(1), 1: lp(2)}
    for n in range(2, D + 1):
        V[n] = lmul(lp(F(2, n), 1), V[n - 2])
    return V[D]


def shares(c):
    return lmul(lp(F(4, 3)), linv(c)), lmul(lp(F(8, 3), -1), c)


def T(c):
    f3, f5 = shares(c)
    return ladd(lp(1), lmul(lp(2), f3), lmul(lp(2), f5))


def check_chord_and_arc():
    circle = lmul(lp(2), ball(2))                     # |S^1| = 2 V_2
    assert circle == {1: F(2)}
    for R in RADII:
        pole = [F(0), F(0), F(0), F(0), R]
        chord = pole[4]                               # distance to the hyperplane x_5 = 0
        arc = lmul(circle, lp(R / 4))
        assert lmul(arc, linv(lp(chord))) == {1: F(1, 2)}
    return True


def check_totals_agree_compositions_differ():
    premise("dark-matter.total-function-thickness")
    c_chord, c_arc = lp(1), lp(F(1, 2), 1)
    assert T(c_chord) == T(c_arc)
    assert T(c_chord) == {0: F(11, 3), -1: F(16, 3)}
    assert shares(c_chord) == ({0: F(4, 3)}, {-1: F(8, 3)})
    assert shares(c_arc) == ({-1: F(8, 3)}, {0: F(4, 3)})
    assert shares(c_chord) != shares(c_arc)
    return True


def check_both_poles_excluded():
    premise("dark-matter.total-function-thickness")
    t2, tpi = T(lp(2)), T(lp(1, 1))
    assert t2 == {0: F(7, 3), -1: F(32, 3)} and tpi == {0: F(19, 3), -1: F(8, 3)}
    lo, hi = bounds(t2)
    assert round(lo * 1000) == round(hi * 1000) == 5729 and (lo - OBS) / SIG > 4
    lo, hi = bounds(tpi)
    assert round(lo * 1000) == round(hi * 1000) == 7182 and (lo - OBS) / SIG > 4
    return True

dark-matter.unit-ball-rule:
"""dark-matter.unit-ball-rule: exact checks.

Numbers of Q(pi) are held as Laurent polynomials in pi with rational coefficients, {k: c} for
sum c pi^k; pi is transcendental, so equal polynomials are equal reals and unequal ones are not.
Decimal comparisons use the rational bounds PI_LO < pi < PI_HI. The unit-ball volumes come from
the recursion V_0 = 1, V_1 = 2, V_D = (2 pi / D) V_(D-2), not from typed values.

Checked:
(1) Under R1 and R2 the density of a tower of space dimension D is m/V_D per unit D-volume; under
    R3 it is read per unit of our three-volume through one unit cell of each unshared direction
    (factor 1^(D-3)), so the share is f = V_3/V_D, with m cancelling (two sample masses): the
    shares are 4/3 at D = 2, 1 at D = 3 and 8/(3 pi) at D = 4.
(2) The dark towers are the five populated residues other than this world's 6, with the census'
    representatives (2,1), (1,2), (4,1), (1,4) and (3,1): residues 1, 7, 3, 5, 2, all causal, of
    space dimensions D = p + q - 1 equal to 2, 2, 4, 4, 3.
(3) The sum V_3 * sum_r 1/V_(D_r) = 1 + 8/3 + 16/(3 pi) = (11 pi + 16)/(3 pi), as an identity in
    pi, lies in (5.36431, 5.36433) and within one sigma (0.065) of 0.1200/0.02237.
Not checked: the sentence that the agreement is a fit is a statement about how the relation was
found, with no computable content.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

PI_LO, PI_HI = F(314159265358, 10 ** 11), F(314159265359, 10 ** 11)
OBS = F(1200, 10000) / F(2237, 100000)        # Planck 2018 Omega_c h^2 / Omega_b h^2
SIG = F(65, 1000)
MASSES = [F(1), F(938, 7)]                    # two sample quantum masses (R1: m cancels)
# the census' representatives of the dark residues (Proposition (ii) of the residue census)
DARK_REPS = [(2, 1), (1, 2), (4, 1), (1, 4), (3, 1)]


def lp(c, k=0):
    return {k: F(c)} if c != 0 else {}


def ladd(*xs):
    out = {}
    for x in xs:
        for k, c in x.items():
            out[k] = out.get(k, F(0)) + c
    return {k: c for k, c in out.items() if c != 0}


def lmul(a, b):
    out = {}
    for k1, c1 in a.items():
        for k2, c2 in b.items():
            out[k1 + k2] = out.get(k1 + k2, F(0)) + c1 * c2
    return {k: c for k, c in out.items() if c != 0}


def linv(a):
    """inverse of a monomial c pi^k"""
    assert len(a) == 1
    (k, c), = a.items()
    return {-k: 1 / c}


def bounds(x):
    lo = hi = F(0)
    for k, c in x.items():
        u, v = c * PI_LO ** k, c * PI_HI ** k
        lo += min(u, v)
        hi += max(u, v)
    return lo, hi


def ball(D):
    V = {0: lp(1), 1: lp(2)}
    for n in range(2, D + 1):
        V[n] = lmul(lp(F(2, n), 1), V[n - 2])
    return V[D]


def share(D, m):
    """our-three-volume density of a tower of space dimension D over ours"""
    rho = lmul(lp(m), linv(ball(D)))            # R1, R2: m per unit ball
    rho = lmul(rho, lp(F(1) ** (D - 3)))         # R3: one unit cell per unshared direction
    rho_us = lmul(lp(m), linv(ball(3)))
    return lmul(rho, linv(rho_us))


def check_shares():
    premise("dark-matter.r1-equal-mass-per-quantum")
    premise("dark-matter.r2-one-quantum-per-unit-ball")
    premise("dark-matter.r3-one-cell-per-unshared-direction")
    assert ball(2) == {1: F(1)} and ball(3) == {1: F(4, 3)} and ball(4) == {2: F(1, 2)}
    for m in MASSES:
        assert share(2, m) == {0: F(4, 3)}
        assert share(3, m) == {0: F(1)}
        assert share(4, m) == {-1: F(8, 3)}
    return True


def check_dark_towers_and_dimensions():
    premise("dark-matter.towers-are-residues-single-clock-filter")
    residues = sorted((p - q) % 8 for p, q in DARK_REPS)
    assert residues == [1, 2, 3, 5, 7]
    assert 6 not in residues and 0 not in residues and 4 not in residues
    assert all(min(p, q) == 1 for p, q in DARK_REPS)
    dims = [p + q - 1 for p, q in DARK_REPS]
    assert dims.count(2) == 2 and dims.count(4) == 2 and dims.count(3) == 1
    return True


def check_total():
    premise("dark-matter.r1-equal-mass-per-quantum")
    premise("dark-matter.r2-one-quantum-per-unit-ball")
    premise("dark-matter.r3-one-cell-per-unshared-direction")
    premise("dark-matter.towers-are-residues-single-clock-filter")
    total = ladd(*[share(p + q - 1, MASSES[1]) for p, q in DARK_REPS])
    # (11 pi + 16)/(3 pi) = 11/3 + (16/3) pi^-1
    assert total == {0: F(11, 3), -1: F(16, 3)}
    assert total == ladd(lp(1), lp(F(8, 3)), lp(F(16, 3), -1))
    lo, hi = bounds(total)
    assert F(536431, 100000) < lo and hi < F(536433, 100000)
    assert max(abs(lo - OBS), abs(hi - OBS)) < SIG
    return True
